type ThinkingLoaderProps = {
  phases?: string[];
  interval?: number;
  phase?: number;
  loop?: boolean;
  done?: boolean;
  doneLabel?: string | ((seconds: number) => string);
  size?: "sm" | "md";
  variant?: "pill" | "plain";
  className?: string;
};
const DEFAULT_PHASES = ["Thinking", "Searching the web", "Reading sources", "Writing response"];
const RAYS = Array.from(
  {
    length: 8,
  },
  (_, i) => i,
);
function ThinkingLoader({
  phases = DEFAULT_PHASES,
  interval = 2200,
  phase,
  loop = false,
  done = false,
  doneLabel = (s) => `Thought for ${s}s`,
  size = "md",
  variant = "pill",
  className,
}: ThinkingLoaderProps) {
  const [step, setStep] = useState(0);
  const [started, setStarted] = useState(() => Date.now());
  const [seconds, setSeconds] = useState<number | null>(null);
  const elapsed = seconds ?? Math.max(1, Math.round((Date.now() - started) / 1000));
  if (done && seconds === null) setSeconds(elapsed);
  if (!done && seconds !== null) {
    setSeconds(null);
    setStarted(Date.now());
    setStep(0);
  }
  useEffect(() => {
    if (done || phase !== undefined || phases.length < 2) return;
    const id = window.setInterval(() => {
      setStep((s) => (s + 1 < phases.length ? s + 1 : loop ? 0 : s));
    }, interval);
    return () => window.clearInterval(id);
  }, [done, phase, phases.length, interval, loop]);
  const index = Math.min(Math.max(phase ?? step, 0), Math.max(phases.length - 1, 0));
  const label = done
    ? typeof doneLabel === "function"
      ? doneLabel(elapsed)
      : doneLabel
    : (phases[index] ?? "");
  const [shown, setShown] = useState({
    key: 0,
    text: label,
  });
  const [leaving, setLeaving] = useState<{
    key: number;
    text: string;
  } | null>(null);
  if (label !== shown.text) {
    setLeaving(shown);
    setShown({
      key: shown.key + 1,
      text: label,
    });
  }
  const box = useRef<HTMLSpanElement>(null);
  const current = useRef<HTMLSpanElement>(null);
  const measured = useRef(false);
  useLayoutEffect(() => {
    const b = box.current;
    const c = current.current;
    if (!b || !c) return;
    if (!measured.current) b.style.transition = "none";
    b.style.width = `${c.offsetWidth + 1}px`;
    if (!measured.current) {
      b.getBoundingClientRect();
      b.style.transition = "";
      measured.current = true;
    }
  }, [shown.key]);
  return (
    <span
      className={["ui-tlc", className].filter(Boolean).join(" ")}
      data-size={size}
      data-variant={variant}
      data-done={done || undefined}
      role="status"
      aria-live="polite"
    >
      {}
      <style href="ui-thinking-loader-clean" precedence="default">
        {css}
      </style>

      <span className="ui-tlc__icon" aria-hidden="true">
        <svg className="ui-tlc__spinner" viewBox="0 0 16 16">
